void main() {
    List<int> scores = new List<int>();
    scores.add(10);
    scores.add(20);
    scores.add(12);
    int sum = 0;
    int i = 0;
    while (i < scores.size()) {
        sum = sum + scores.get(i);
        i = i + 1;
    }
    Text message = new Text("Somme = ");
    message.appendInt(sum);
    message.print();
    println(scores.remove(1));
    println(scores.pop());
    println(scores.size());
}

interface Named {
    readonly String name();
}
class Person implements Named {
    private String value;
    public Person(String value) { this.value = value; }
    public readonly String name() { return this.value; }
}
void main() {
    List<Named> people = new List<Named>();
    Person alice = new Person("Alice");
    people.add(alice); // Transfert; alice n'est plus utilisable.
    people.add(new Person("Bob"));
    Named first = people.remove(0);
    println(first.name());
    // Vider la liste detruit Bob, mais pas Alice extraite par remove.
    people.clear();
    println(first.name());
    println(people.isEmpty());
}

class Node {
    private int value;
    private List<Node> children = new List<Node>();
    public Node(int value) { this.value = value; }
    public void add(Node child) { this.children.add(child); }
    public Node detachLast() { return this.children.pop(); }
    public readonly int getValue() { return this.value; }
}
